const url = "http://172.21.0.2:8181/mcp";

async function rpc(body, sessionId) {
  const headers = { "Content-Type": "application/json", "Accept": "application/json, text/event-stream" };
  if (sessionId) headers["Mcp-Session-Id"] = sessionId;
  const res = await fetch(url, { method: "POST", headers, body: JSON.stringify(body) });
  const sid = res.headers.get("mcp-session-id");
  const text = await res.text();
  // handle SSE or plain JSON
  let data = null;
  if (text.startsWith("event:") || text.startsWith("data:")) {
    for (const line of text.split("\n")) {
      if (line.startsWith("data:")) { try { data = JSON.parse(line.slice(5).trim()); } catch {} }
    }
  } else {
    try { data = JSON.parse(text); } catch {}
  }
  return { status: res.status, sessionId: sid, data, raw: text.slice(0, 2000) };
}

const init = await rpc({ jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: "2025-03-26", capabilities: {}, clientInfo: { name: "probe", version: "1.0" } } });
const sid = init.sessionId;
await rpc({ jsonrpc: "2.0", method: "notifications/initialized" }, sid);
const tools = await rpc({ jsonrpc: "2.0", id: 2, method: "tools/list", params: {} }, sid);
return { init: { status: init.status, data: init.data }, tools: tools.data };

